      await new Promise((r) => setTimeout(r, 10));
    }
    assert.deepEqual(
      (await list()).map((b) => b.key),
      ["done.txt"],
    );

    finish();
    assert.equal(await response, 201);
    const byKey = new Map((await list()).map((b) => [b.key, b]));
    assert.equal(byKey.get("pending.bin")?.sha256, sha256(content));
    assert.equal(byKey.get("pending.bin")?.size, content.length);
  });

  it("answers HEAD with 200 and no body", async () => {
    await put("x", "x");
    const res = await fetch(url("/blobs"), { method: "HEAD" });
    assert.equal(res.status, 200);
    assert.equal(res.headers.get("content-type"), "application/json; charset=utf-8");
    assert.equal(await res.text(), "");
  });

  it("stays consistent while PUTs and DELETEs reshape the tree", async () => {
    // `flip` keeps switching between being a blob and a directory of blobs.
    let active = true;
    const churn = (async () => {
      for (let i = 0; active; i++) {
        await put("flip/child", `child ${i}`);
        await del("flip/child");
        await put("flip", `file ${i}`);
        await del("flip");
      }
    })();
    const writers = Array.from({ length: 4 }, async (_, w) => {
      for (let i = 0; active; i++) {
        await put(`stable/${w}`, `writer ${w} round ${i}`);
      }
    });

    try {
      for (let round = 0; round < 50; round++) {
        for (const blob of await list()) {
          assert.ok(["flip", "flip/child"].includes(blob.key) || blob.key.startsWith("stable/"), blob.key);
          assert.match(blob.sha256, /^[0-9a-f]{64}$/);
          assert.ok(Number.isInteger(blob.size) && blob.size >= 0);
          assert.ok(!Number.isNaN(Date.parse(blob.modified_at)));
        }
      }
    } finally {
      active = false;
      await Promise.all([churn, ...writers]);
    }

    const listed = await list();
    assert.deepEqual(
      listed.map((b) => b.key),
      ["stable/0", "stable/1", "stable/2", "stable/3"],
    );
    for (const blob of listed) {
      const res = await fetch(url(`/blobs/${blob.key}`));
      const body = Buffer.from(await res.arrayBuffer());
      assert.equal(blob.sha256, sha256(body), blob.key);
      assert.equal(blob.size, body.length, blob.key);
    }
  });
});
import assert from "node:assert/strict";
import { mkdir, mkdtemp, readdir, readFile, readlink, rm, symlink, writeFile } from "node:fs/promises";
import http from "node:http";
import net from "node:net";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { Readable } from "node:stream";
import { after, before, beforeEach, describe, it } from "node:test";

import { BlobStore, InvalidKeyError } from "../src/blobs.js";
import { startServer, type RunningServer } from "../src/server.js";

/** Every file and directory under `dir`, as sorted relative paths. */
async function tree(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { recursive: true });
  return entries.map((e) => e.toString()).sort();
}

/**
 * Keys that escape the store once resolved, or resolve to the root itself.
 * parseKey() never lets them through; BlobStore has to refuse them anyway.
 */
const ESCAPING_KEYS = ["..", "../escape", "a/../../escape", "a/b/../../../escape", ".", "a/..", ""];

describe("BlobStore rejects keys that resolve outside the store", () => {
  let root: string;
  let dataDir: string;
  let store: BlobStore;

  before(async () => {
    root = await mkdtemp(join(tmpdir(), "syncbox-traversal-"));
    // A relative data dir, as --data-dir may be given.
    dataDir = relative(process.cwd(), join(root, "data"));
    store = new BlobStore(dataDir);
    await store.put("a/b/keep", Readable.from(["keep"]));
    await writeFile(join(root, "escape"), "outside");
  });

  after(async () => {
    await rm(root, { recursive: true, force: true });
  });

  for (const key of ESCAPING_KEYS) {
    it(`refuses ${JSON.stringify(key)} on put, open and delete`, async () => {
      const before = await tree(root);
      await assert.rejects(store.put(key, Readable.from(["evil"])), InvalidKeyError);
      await assert.rejects(store.open(key), InvalidKeyError);
      await assert.rejects(store.delete(key), InvalidKeyError);
      assert.deepEqual(await tree(root), before);
      assert.equal(await readFile(join(root, "escape"), "utf8"), "outside");
    });
  }

  it("leaves no temporary files behind after a refused put", async () => {
    assert.deepEqual(await readdir(join(dataDir, "tmp")), []);
  });
});

